mapper.select:
SELECT 'ORD-' || o.idempotency_key AS orderId, o.account_id AS accountId, i.symbol AS symbol, o.side AS side, CAST(o.quantity AS BIGINT) AS quantity, o.price AS price, CASE WHEN o.status = 'FILLED' THEN o.price ELSE NULL END AS executedPrice, o.status AS status, o.idempotency_key AS idempotencyKey, o.received_at AS createdOn FROM orders o JOIN instrument i ON o.instrument_id = i.instrument_id WHERE o.account_id = #{accountId}
AND o.status = #{status}
AND o.received_at >= #{from}
AND o.received_at <= #{to}
ORDER BY o.received_at DESC, o.order_id DESC
